    'welcomeTitle': {AppLanguage.en: 'Welcome', AppLanguage.ar: 'مرحبًا بك', AppLanguage.fr: 'Bienvenue'},
    'wnWelcome1': {AppLanguage.en: 'Prayer times for Edmonton, calculated on your device.', AppLanguage.ar: 'مواقيت الصلاة لإدمونتون، تُحسب على جهازك.', AppLanguage.fr: 'Les heures de prière pour Edmonton, calculées sur votre appareil.'},
    'wnWelcome2': {AppLanguage.en: 'An alert at every prayer with your choice of adhan sounds.', AppLanguage.ar: 'تنبيه عند كل صلاة بصوت الأذان الذي تختاره.', AppLanguage.fr: 'Une alerte à chaque prière avec le son d\'adhan de votre choix.'},
    'wnWelcome3': {AppLanguage.en: 'Home-screen widgets in your own colors.', AppLanguage.ar: 'ودجت للشاشة الرئيسية بألوانك الخاصة.', AppLanguage.fr: 'Des widgets pour votre écran d\'accueil, dans vos couleurs.'},
    'wnWelcome4': {AppLanguage.en: 'A verse and a hadith of the day, every day, right on the Home screen.', AppLanguage.ar: 'آية وحديث اليوم، كل يوم، في الشاشة الرئيسية.', AppLanguage.fr: 'Un verset et un hadith du jour, chaque jour, sur l\'écran d\'accueil.'},
    'wnTest230': {AppLanguage.en: 'Send a test alert from Settings and hear your adhan exactly as a real prayer alert will sound.', AppLanguage.ar: 'أرسل تنبيهًا تجريبيًا من الإعدادات واسمع الأذان كما سيصلك في تنبيه الصلاة الحقيقي.', AppLanguage.fr: 'Envoyez une alerte test depuis les Réglages et entendez votre adhan exactement comme une vraie alerte de prière.'},
    'wnHealth230': {AppLanguage.en: 'A new alerts health check confirms your notifications, exact alarms and battery settings are ready.', AppLanguage.ar: 'فحص جديد لصحة التنبيهات يؤكد جاهزية الإشعارات والمنبّهات الدقيقة وإعدادات البطارية.', AppLanguage.fr: 'Une nouvelle vérification des alertes confirme que vos notifications, alarmes exactes et réglages de batterie sont prêts.'},
    'wnHadith230': {AppLanguage.en: 'A hadith of the day now sits under the daily verse on the Home screen.', AppLanguage.ar: 'حديث اليوم أصبح الآن تحت آية اليوم في الشاشة الرئيسية.', AppLanguage.fr: 'Un hadith du jour se trouve maintenant sous le verset du jour sur l\'écran d\'accueil.'},
    'wnNames230': {AppLanguage.en: 'The 99 Names of Allah, with meanings, one tap from the Home screen.', AppLanguage.ar: 'أسماء الله الحسنى بمعانيها، بضغطة واحدة من الشاشة الرئيسية.', AppLanguage.fr: 'Les 99 noms d\'Allah, avec leurs significations, à un toucher de l\'écran d\'accueil.'},
    'wnHijri230': {AppLanguage.en: 'Countdowns to Ramadan, the Eids and the other Islamic dates, on the Home screen.', AppLanguage.ar: 'عدّ تنازلي لرمضان والعيدين وبقية المناسبات الإسلامية، في الشاشة الرئيسية.', AppLanguage.fr: 'Des comptes à rebours vers Ramadan, les Aïds et les autres dates islamiques, sur l\'écran d\'accueil.'},
    'testAlertSent': {AppLanguage.en: 'Test alert sent — check your notifications.', AppLanguage.ar: 'تم إرسال التنبيه التجريبي — تحقق من إشعاراتك.', AppLanguage.fr: 'Alerte test envoyée — vérifiez vos notifications.'},
    // v3.0.0: What's New rows
    'wnName300': {AppLanguage.en: 'A new name: the app is now Prayer YEG, an independent third-party app.', AppLanguage.ar: 'اسم جديد: أصبح التطبيق الآن Prayer YEG، تطبيقًا مستقلًا من طرف ثالث.', AppLanguage.fr: "Un nouveau nom : l'app s'appelle maintenant Prayer YEG, une app indépendante d'un développeur tiers."},
    'wnQuran300': {AppLanguage.en: 'The full Quran player is here: every surah in Arabic or English, with the text following the recitation.', AppLanguage.ar: 'وصل مشغّل القرآن الكامل: كل سورة بالعربية أو الإنجليزية، مع نص يتبع التلاوة.', AppLanguage.fr: 'Le lecteur de Coran complet est là : chaque sourate en arabe ou en anglais, avec le texte qui suit la récitation.'},
    'wnDownloads300': {AppLanguage.en: 'Download whole surahs, or a whole voice at once, and listen offline.', AppLanguage.ar: 'نزّل سورًا كاملة، أو صوتًا كاملًا دفعة واحدة، واستمع دون اتصال.', AppLanguage.fr: "Téléchargez des sourates entières, ou une voix entière d'un coup, et écoutez hors ligne."},
    'wnSleep300': {AppLanguage.en: 'A sleep timer fades the recitation out gently before it stops.', AppLanguage.ar: 'مؤقّت نوم يخفّض صوت التلاوة تدريجيًا قبل إيقافها.', AppLanguage.fr: "Une minuterie de sommeil fait baisser la récitation en douceur avant l'arrêt."},
    'wnMemo300': {AppLanguage.en: 'Memorization tools: repeat one ayah or loop a range, and bookmark ayahs to return to.', AppLanguage.ar: 'أدوات للحفظ: كرّر آية واحدة أو كرّر نطاقًا من الآيات، واحفظ علامات للآيات لتعود إليها.', AppLanguage.fr: 'Outils de mémorisation : répétez un verset ou une plage en boucle, et marquez des versets pour y revenir.'},
    'wnTracker300': {AppLanguage.en: 'A prayer tracker on the Home screen: check off each prayer and watch your streak grow.', AppLanguage.ar: 'متتبّع للصلاة في الشاشة الرئيسية: علّم كل صلاة وراقب سلسلة أيامك تكبر.', AppLanguage.fr: "Un suivi des prières sur l'écran d'accueil : cochez chaque prière et regardez votre série grandir."},
